import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Historial","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/history.md","filePath":"es-ES/user-guide/settings/history.md","lastUpdated":1787586465000}'),t={name:"es-ES/user-guide/settings/history.md"};function i(l,a,n,d,c,u){return r(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="historial" tabindex="-1">Historial <a class="header-anchor" href="#historial" aria-label="Permalink to &quot;Historial&quot;">​</a></h1><p>La página de Historial gestiona los registros de uso y las prioridades de reapertura adaptativa. Contiene dos pestañas: <strong>Historial de búsqueda</strong> e <strong>Historial de palabras clave</strong>.</p><h2 id="_1-historial-de-busqueda" tabindex="-1">1. Historial de búsqueda <a class="header-anchor" href="#_1-historial-de-busqueda" aria-label="Permalink to &quot;1. Historial de búsqueda&quot;">​</a></h2><p>Registra los resultados ejecutados asociando el término de búsqueda con la ruta física del elemento:</p><ul><li><strong>Reapertura adaptativa priorizada</strong>: Al escribir caracteres similares a consultas anteriores, Lertaro prioriza los elementos abiertos previamente en la parte superior. Por ejemplo, si abriste <code>BCompare.exe</code> buscando <code>bcomp</code>, una búsqueda futura de <code>bc</code> lo destacará al inicio.</li><li><strong>Agrupación en la Ventana incrustada</strong>: En los diálogos de archivos, las coincidencias del historial dentro de la carpeta activa se clasifican en &quot;Carpeta actual&quot; y las demás en &quot;Búsqueda global&quot;.</li><li><strong>Filtrado de rutas inexistentes</strong>: Si un archivo ha sido eliminado o movido externamente, se omite de forma automática, evitando enlaces rotos y resultados duplicados.</li><li><strong>Opciones de gestión</strong>: <ul><li><strong>Habilitar historial</strong>: Interruptor general; al desactivarlo se conservan los registros existentes pero no se añaden nuevos.</li><li><strong>Filtro de búsqueda</strong>: Permite filtrar las entradas visibles.</li><li><strong>Eliminación individual y borrado total</strong>: Elimina filas individuales o pulsa <strong>Borrar todo el historial</strong>.</li></ul></li></ul><h2 id="_2-historial-de-palabras-clave" tabindex="-1">2. Historial de palabras clave <a class="header-anchor" href="#_2-historial-de-palabras-clave" aria-label="Permalink to &quot;2. Historial de palabras clave&quot;">​</a></h2><p>Memoriza las <strong>cadenas de búsqueda originales</strong> tecleadas en la Ventana rápida:</p><ul><li><strong>Navegación por atajos</strong>: En la Ventana rápida, pulsa <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> para retroceder o avanzar entre consultas recientes. Pulsa <strong><code>Ctrl+Delete</code></strong> para borrar el término activo.</li><li><strong>Gestión independiente</strong>: Dispone de su propio interruptor de activación, filtro, eliminación individual y botón de <strong>Borrar todo el historial</strong>.</li></ul>',8)])])}const h=e(t,[["render",i]]);export{g as __pageData,h as default};
